changeSet.sql:
ALTER TABLE ${ARENA_DB_SCHEMA}.academy_running_session ADD COLUMN version BIGINT NOT NULL DEFAULT 0,
 ADD COLUMN original_amount DECIMAL(12,2), ADD COLUMN approved_discount DECIMAL(12,2) NOT NULL DEFAULT 0,
 ADD COLUMN requested_discount DECIMAL(12,2) NOT NULL DEFAULT 0, ADD COLUMN discount_status VARCHAR(16) NOT NULL DEFAULT 'NONE',
 ADD COLUMN discount_reason VARCHAR(500), ADD COLUMN discount_request_id BIGINT;
-- Historical gross cannot be reconstructed where old discounts were not recorded. Preserve the stored bill as opening gross/net.
UPDATE ${ARENA_DB_SCHEMA}.academy_running_session SET original_amount=total_amount WHERE total_amount IS NOT NULL;
ALTER TABLE ${ARENA_DB_SCHEMA}.academy_running_session ADD CONSTRAINT session_discount_bounds CHECK(approved_discount>=0 AND requested_discount>=0 AND (original_amount IS NULL OR approved_discount<=original_amount));
CREATE UNIQUE INDEX session_id_academy_scope ON ${ARENA_DB_SCHEMA}.academy_running_session(id,academy_id);
ALTER TABLE ${ARENA_DB_SCHEMA}.academy_staff ADD COLUMN discount_enabled BOOLEAN NOT NULL DEFAULT FALSE,
 ADD COLUMN max_discount_percent DECIMAL(5,2) NOT NULL DEFAULT 0, ADD COLUMN max_discount_amount DECIMAL(12,2) NOT NULL DEFAULT 0,
 ADD COLUMN daily_discount_allowance DECIMAL(12,2), ADD COLUMN discount_approval_allowed BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE ${ARENA_DB_SCHEMA}.academy_staff ADD CONSTRAINT staff_discount_bounds CHECK(max_discount_percent BETWEEN 0 AND 100 AND max_discount_amount>=0 AND (daily_discount_allowance IS NULL OR daily_discount_allowance>=0));
CREATE TABLE ${ARENA_DB_SCHEMA}.session_stop_quote (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, token_hash VARCHAR(64) NOT NULL UNIQUE,
 academy_id BIGINT NOT NULL, session_id BIGINT NOT NULL, session_version BIGINT NOT NULL, actor_id BIGINT NOT NULL,
 captured_at TIMESTAMP NOT NULL, expires_at TIMESTAMP NOT NULL, consumed_at TIMESTAMP,
 billable_seconds BIGINT NOT NULL, paused_seconds BIGINT NOT NULL, original_amount DECIMAL(12,2) NOT NULL,
 FOREIGN KEY(session_id,academy_id) REFERENCES ${ARENA_DB_SCHEMA}.academy_running_session(id,academy_id)
);
CREATE INDEX session_quote_expiry ON ${ARENA_DB_SCHEMA}.session_stop_quote(expires_at);
CREATE TABLE ${ARENA_DB_SCHEMA}.session_discount_request (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, academy_id BIGINT NOT NULL, session_id BIGINT NOT NULL,
 amount DECIMAL(12,2) NOT NULL CHECK(amount>0), reason VARCHAR(500) NOT NULL,
 status VARCHAR(16) NOT NULL CHECK(status IN ('PENDING','APPROVED','REJECTED','CANCELLED')),
 requested_by_id BIGINT NOT NULL, requested_by VARCHAR(100) NOT NULL, staff_id BIGINT,
 requested_at TIMESTAMP NOT NULL, decided_by_id BIGINT, decided_by VARCHAR(100), decided_at TIMESTAMP,
 decision_reason VARCHAR(500), policy_snapshot VARCHAR(1000) NOT NULL,
 FOREIGN KEY(session_id,academy_id) REFERENCES ${ARENA_DB_SCHEMA}.academy_running_session(id,academy_id)
);
CREATE UNIQUE INDEX session_pending_discount ON ${ARENA_DB_SCHEMA}.session_discount_request(session_id) WHERE status='PENDING';
CREATE INDEX session_discount_scope_status ON ${ARENA_DB_SCHEMA}.session_discount_request(academy_id,status,requested_at);
ALTER TABLE ${ARENA_DB_SCHEMA}.academy_payment ALTER COLUMN student_id DROP NOT NULL;
ALTER TABLE ${ARENA_DB_SCHEMA}.academy_payment ADD COLUMN session_id BIGINT,
 ADD CONSTRAINT payment_subject CHECK ((student_id IS NOT NULL AND session_id IS NULL) OR (student_id IS NULL AND session_id IS NOT NULL)),
 ADD CONSTRAINT payment_session_scope FOREIGN KEY(session_id,academy_id) REFERENCES ${ARENA_DB_SCHEMA}.academy_running_session(id,academy_id);
CREATE INDEX session_payment_dates ON ${ARENA_DB_SCHEMA}.academy_payment(academy_id,payment_date,session_id) WHERE session_id IS NOT NULL;
-- Opening balances preserve existing collections without inventing payment dates. Mark the best available legacy date explicitly.
INSERT INTO ${ARENA_DB_SCHEMA}.academy_payment(academy_id,session_id,amount,payment_date,method,reference,notes,recorded_at,recorded_by)
 SELECT academy_id,id,paid_amount,COALESCE(stopped_at,ended_at,started_at)::date,'OTHER','LEGACY_SESSION_OPENING',
 'Imported opening collection; actual historical payment date unavailable',COALESCE(stopped_at,ended_at,started_at),COALESCE(stopped_by,started_by)
 FROM ${ARENA_DB_SCHEMA}.academy_running_session WHERE paid_amount>0;
